export type Word = {
  word: string;
  stress?: string;
  pronunciation?: string;
  meaning?: string;
  sound?: string;
  // Korean spelling the narration actually uses for this word, when it isn't
  // already captured by `pronunciation`. Never rendered — it exists only so
  // scripts/generate-highlights.mjs can align the word to the transcript.
  narrationCue?: string;
  // Scene-relative frames spanning the moment the narration actually says
  // this word, generated by scripts/generate-highlights.mjs. Drives both the
  // per-item activation and the on-word speech emphasis. Optional: words the
  // transcript couldn't confidently align simply never activate.
  highlightAt?: number;
  highlightEnd?: number;
  // compare layout: the substring to color yellow (e.g. a suffix like "TION").
  highlightPart?: string;
  // compare layout: the single character that explains the difference between
  // the two words being compared (e.g. the "S" in QUESTION), colored red.
  // Left undefined for the side that has no such cause.
  causeChar?: string;
};

export type SceneLayout = "quiz" | "wordList" | "ruleBox" | "compare" | "summary";

/** Section kind shown as the card's badge; drives the badge colour. */
export type CardCategory =
  | "intro"
  | "principle"
  | "example"
  | "quiz"
  | "exception"
  | "summary"
  | "teaser"
  /**
   * Closing card. Carries no narration and no card body — it exists to hold
   * the frame while YouTube lays its own end-screen elements over it, so the
   * layout is defined by where those elements land rather than by content.
   */
  | "endscreen";

/**
 * One word rendered as a syllable table in the card layout: the English
 * spelling split into cells with the stressed one marked, and the Korean
 * reading split the same way. Stress and deviant sounds are conveyed purely
 * by colour — no "(강세)" style text labels anywhere.
 */
export type CardWord = {
  word: string;
  /** e.g. ["IN", "FOR", "MA", "TION"] */
  syllables: string[];
  /** Index into `syllables` carrying the stress (yellow). */
  stressIndex?: number;
  /** Korean reading cells, e.g. ["인", "포", "메", "이", "션"] */
  pronCells?: string[];
  /** Index into `pronCells` carrying the stress (yellow). */
  pronStressIndex?: number;
  /** Index into `pronCells` whose sound deviates — 천/전 (red). */
  pronDiffIndex?: number;
};

export type CardPair = { from: CardWord; to: CardWord };

/** Which landmark glyph a `flow` stage shows — see src/components/languageIcons.tsx. */
export type FlowIconName = "latin" | "french" | "english";

/**
 * `icon` is optional because only EP6's flow is a journey between *languages*
 * (Latin -> French -> English), where a landmark reads as the stage itself.
 * EP7-9 use the same flow layout for stages of a sound change ("모음(떨림)"
 * -> "떨림이 이어짐" -> "전"), which no landmark represents — those render
 * label-only.
 */
export type FlowStage = { label: string; icon?: FlowIconName };

/**
 * On-screen content for the `card` motion style, taken from the EP6
 * storyboard. Kept separate from the fields calm/dynamic/reference read, so
 * those styles are unaffected.
 *
 * Note: the storyboard's scene number and category caption are production
 * annotations and are deliberately not rendered — only `badge` and
 * `timecode` appear on screen.
 */
export type SceneCard = {
  category: CardCategory;
  badge: string;
  heading?: string;
  /** Free-text lines stacked in the card body. */
  lines?: string[];
  /** Boxed callout inside the card. */
  box?: string[];
  words?: CardWord[];
  pairs?: CardPair[];
  /** Numbered points (summary). */
  points?: string[];
  /** Small word chips (summary). */
  chips?: string[];
  /** Etymology-style flow, e.g. Latin → French → English, each with its landmark icon. */
  flow?: FlowStage[];
  /** Closing line under the card body. */
  note?: string;
  /** The card's own bottom line. */
  caption?: string;
  /** endscreen only: the two calls to action. */
  subscribe?: string;
  playlist?: string;
  playlistUrl?: string;
};

/** One narration phrase with its scene-relative frame range. */
export type SubtitleCue = { text: string; from: number; to: number };

export type Scene = {
  id: number;
  title: string;
  duration: number;
  layout: SceneLayout;
  words: Word[];
  content?: string | string[];
  caption: string;
  narration: string;
  /** On-screen content for the `card` style only. */
  card?: SceneCard;
  /**
   * Sentence-level narration subtitles with no gaps between them — what the
   * card style displays. Generated by scripts/generate-highlights.mjs, which
   * pages whisper's *segment* output with @remotion/captions'
   * createTikTokStyleCaptions() (the token pass mangles Korean; see CLAUDE.md).
   */
  subtitleGroups?: SubtitleCue[];
};

export type EpisodeData = {
  episode: string;
  title: string;
  scenes: Scene[];
};

/**
 * One beat of a vertical short (1080x1920). Separate from `Scene` on purpose:
 * shorts have no layout/card/words machinery, just a single word or a
 * countdown or a CTA, and the long-form styles never read this.
 *
 * `start`/`end` in the script are the draft plan — the real screen duration
 * comes from the generated narration's measured length.
 */
export type ShortsSegment = {
  id: number;
  start: number;
  end: number;
  narration: string;
  /** English spelling shown centre-screen. */
  word?: string;
  /** Korean syllable carrying the stress, highlighted in `pronunciation`. */
  stress?: string;
  /**
   * The English letters carrying the stress. Needed because `stress` is the
   * Korean syllable, which cannot be located inside the English spelling.
   */
  stressEn?: string;
  pronunciation?: string;
  /** Renders the 3-2-1 countdown instead of a word. */
  countdown?: boolean;
  /**
   * Compare beat: the naive mis-reading struck through on the left, the real
   * pronunciation on the right.
   *
   * The mis-reading is **screen-only**. It must never appear in `narration` —
   * having the narrator say "스테이 티온" would teach the wrong thing, and a
   * fragment like that is exactly what the TTS mangles. scripts/generate-tts.mjs
   * enforces the split.
   */
  compareLeft?: { label: string; text: string };
  compareRight?: {
    label: string;
    word: string;
    /** Korean syllable carrying the stress, highlighted in `pronunciation`. */
    stress: string;
    /**
     * The English letters carrying the stress. Needed because `stress` is the
     * Korean syllable, which cannot be located inside the English spelling.
     */
    stressEn?: string;
    pronunciation: string;
  };
  /** Closing call-to-action pill. */
  cta?: string;
  /**
   * Fires the reveal chime on `highlightAt`. Only the answer beat sets it —
   * the opening word is meant to arrive in silence.
   */
  reveal?: boolean;
  /** Scene-relative frames, generated by scripts/generate-highlights.mjs. */
  highlightAt?: number;
  highlightEnd?: number;
  subtitleGroups?: SubtitleCue[];
};

export type ShortsData = {
  title: string;
  /**
   * Hook held under the player's top icons for the whole short. Optional —
   * a short whose own content carries the hook (the compare layout) does not
   * need one.
   */
  header?: string[];
  segments: ShortsSegment[];
};

/** One of the three words tested in EP07-shortsA's "which reads how" beat. */
export type ShortsAPillWord = "PASSION" | "MISSION" | "DECISION";

/**
 * One beat of EP07-shortsA (1080x1920). A dedicated type rather than reusing
 * `ShortsSegment`: here `countdown` is a digit *count* and `reveal` names
 * *which* pill word is being answered, both incompatible with EP06 shorts'
 * boolean fields of the same names.
 */
export type ShortsASegment = {
  id: number;
  /** Draft plan (seconds); the real screen duration comes from the audio. */
  start: number;
  end: number;
  narration: string;
  /** Renders a countdown of this many digits (5, 4, 3, ...) instead of content. */
  countdown?: number;
  /** Which opening pill this beat answers. */
  reveal?: ShortsAPillWord;
  /** Korean syllable carrying the stress, highlighted in `pronunciation`. */
  stress?: string;
  pronunciation?: string;
  /** Closing call-to-action pill. */
  cta?: string;
  subtitleGroups?: SubtitleCue[];
};

export type ShortsAData = {
  title: string;
  /** The three pill words shown together at 0-2s, before any are answered. */
  openingWords: ShortsAPillWord[];
  segments: ShortsASegment[];
};
